sys_script_include.script:
function TargetInstanceGetStatus(
	grInstance,
	aWhitelistPlugins,
	aWhitelistStoreApps)
{
	var GetValue = x_snc_devtools.GetValue;
	var GetArrayValue = x_snc_devtools.GetArrayValue;
	var GetStringValue = x_snc_devtools.GetStringValue;
	var IsObject = x_snc_devtools.IsObject;
	var MakeUrlParameters = x_snc_devtools.MakeUrlParameters;

	aWhitelistPlugins = GetArrayValue(aWhitelistPlugins);
	aWhitelistStoreApps = GetArrayValue(aWhitelistStoreApps);

	var strEndPoint =
		'x_snc_deployer/target/get_status';

	var params = {};
	if (aWhitelistPlugins.length > 0)
	{
		params.plugins = aWhitelistPlugins;
	}
	if (aWhitelistStoreApps.length > 0)
	{
		params.store_apps = aWhitelistStoreApps;
	}
	var strParams = MakeUrlParameters(params);
	if (strParams != '')
	{
		strEndPoint += '?' + strParams;
	}

	var result =
		TargetInstanceRequest(
			grInstance,
			strEndPoint);

	var status =
		GetValue(
			result,
			'result');

	if (IsObject(status) != true)
	{
		return false;
	}

	return status;
}
